def base(expr):
    e = expr.strip().rstrip(';')
    return e.split('->')[-1].split('.')[-1].strip()

re_spin_plain = re.compile(r'\bspin_lock\s*\(\s*&?([^),]+)')
re_deffn = re.compile(r'^[A-Za-z_][A-Za-z0-9_ \t\*]*\(')

def fn_defs(lines):
    defs = []  # (lineno, name)
    for i, l in enumerate(lines):
        if re.match(r'^[A-Za-z_]', l) and '(' in l and not l.strip().endswith(';'):
            m = re.match(r'^.*?([A-Za-z_][A-Za-z0-9_]*)\s*\(', l)
            if m:
                nm = m.group(1)
                if nm in ('if','for','while','switch','return','sizeof'): continue
                defs.append((i+1, nm, l.strip()[:70]))
    return defs

rows = []
for path, hs in handler_locks.items():
    try:
        with open(path,'r',errors='replace') as fh:
            lines = fh.read().split('\n')
    except Exception:
        continue
    defs = fn_defs(lines)
    def enclosing(lineno):
        best = ('?', '?')
        for (dl, nm, txt) in defs:
            if dl <= lineno:
                best = (nm, txt)
            else:
                break
        return best
    rel = path.replace(BASE+'/','')
    for h, info in hs.items():
        plains = [x for x in info['locks'] if x[1]=='plain']
